import csv
import json
from pathlib import Path

import numpy as np
import stan


APP_DIR = Path("/app")

STAN_CODE = r'''
functions {
  matrix cov_ard_sqexp(matrix X, vector rho, real alpha, real jitter) {
    int N = rows(X);
    int D = cols(X);
    matrix[N, N] K;

    for (i in 1:N) {
      K[i, i] = square(alpha) + jitter;
      for (j in (i + 1):N) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X[j, d]) / rho[d];
          s += t * t;
        }
        K[i, j] = square(alpha) * exp(-0.5 * s);
        K[j, i] = K[i, j];
      }
    }
    return K;
  }

  matrix cross_cov_ard(matrix X, matrix X_new, vector rho, real alpha) {
    int N = rows(X);
    int M = rows(X_new);
    int D = cols(X);
    matrix[N, M] Kx;
    for (i in 1:N) {
      for (j in 1:M) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X_new[j, d]) / rho[d];
          s += t * t;
        }
        Kx[i, j] = square(alpha) * exp(-0.5 * s);
      }
    }
    return Kx;
  }
}

data {
  int<lower=1> N;
  int<lower=1> D;
  matrix[N, D] X;
  int<lower=1> P;
  matrix[N, P] H;
  vector[N] y;
  real<lower=0> jitter;

  int<lower=0> N_new;
  matrix[N_new, D] X_new;
  matrix[N_new, P] H_new;
}

parameters {
  vector[P] beta;
  real<lower=0> alpha;
  vector<lower=0>[D] rho;
  real<lower=0> sigma;
}

transformed parameters {
  vector[N] mu = H * beta;
  matrix[N, N] K = cov_ard_sqexp(X, rho, alpha, jitter)
                   + diag_matrix(rep_vector(square(sigma), N));
  matrix[N, N] L_K = cholesky_decompose(K);
}

model {
  beta  ~ normal(0, 1);
  alpha ~ normal(0, 1.5);
  rho   ~ lognormal(0, 1);
  sigma ~ normal(0, 0.5);
  y ~ multi_normal_cholesky(mu, L_K);
}

generated quantities {
  vector[N_new] y_new;
  if (N_new > 0) {
    matrix[N, N_new] K_x_xnew = cross_cov_ard(X, X_new, rho, alpha);
    matrix[N_new, N_new] K_new = cov_ard_sqexp(X_new, rho, alpha, jitter);
    vector[N] resid = y - (H * beta);

    vector[N] alpha_vec = mdivide_left_tri_low(L_K, resid);
    alpha_vec = mdivide_left_tri_low(L_K', alpha_vec);

    vector[N_new] f_mean = (K_x_xnew' * alpha_vec);
    matrix[N, N_new] v = mdivide_left_tri_low(L_K, K_x_xnew);
    vector[N_new] f_var = to_vector(diagonal(K_new)) - to_vector(columns_dot_self(v));
    for (m in 1:N_new) {
      real m_mean = (H_new[m] * beta) + f_mean[m];
      real m_sd   = sqrt(f_var[m] + square(sigma));
      y_new[m] = normal_rng(m_mean, m_sd);
    }
  }
}
'''


def read_csv_matrix(path: Path, expected_columns: int | None = None) -> np.ndarray:
    with path.open(newline="") as file:
        rows = list(csv.reader(file))
    if not rows:
        raise ValueError(f"CSV file is empty: {path}")
    values = np.asarray([[float(value) for value in row] for row in rows[1:]], dtype=float)
    if values.ndim == 1:
        values = values.reshape(-1, len(rows[0]))
    if expected_columns is not None and values.shape[1] != expected_columns:
        raise ValueError(f"Unexpected column count in {path}: {values.shape[1]}")
    return values


def main() -> None:
    train_X = read_csv_matrix(APP_DIR / "train_X.csv", expected_columns=3)
    test_X = read_csv_matrix(APP_DIR / "test_X.csv", expected_columns=train_X.shape[1])
    train_y_matrix = read_csv_matrix(APP_DIR / "train_y.csv", expected_columns=1)
    train_y = train_y_matrix[:, 0]

    with (APP_DIR / "meta_public.json").open() as file:
        meta = json.load(file)

    P = int(meta["P"])
    jitter = float(meta["jitter"])
    N, D = train_X.shape
    N_new = test_X.shape[0]
    if P != 3:
        raise ValueError(f"This model construction expects P=3, got {P}")

    H = np.column_stack((np.ones(N), train_X[:, 0], train_X[:, 1]))
    H_new = np.column_stack((np.ones(N_new), test_X[:, 0], test_X[:, 1]))

    data = {
        "N": int(N),
        "D": int(D),
        "X": train_X.tolist(),
        "P": P,
        "H": H.tolist(),
        "y": train_y.tolist(),
        "jitter": jitter,
        "N_new": int(N_new),
        "X_new": test_X.tolist(),
        "H_new": H_new.tolist(),
    }

    posterior = stan.build(STAN_CODE, data=data, random_seed=1)
    fit = posterior.sample(
        num_chains=4,
        num_samples=1000,
        num_warmup=1000,
        num_thin=2,
        save_warmup=False,
        init_radius=0.1,
        delta=0.93,
        max_depth=14,
        gamma=0.05,
        kappa=0.75,
        t0=10,
        init_buffer=100,
        term_buffer=50,
        window=25,
    )

    alpha_mean = float(np.mean(fit["alpha"]))
    sigma_mean = float(np.mean(fit["sigma"]))
    rho_mean = np.mean(fit["rho"], axis=1)
    beta_mean = np.mean(fit["beta"], axis=1)

    np.savetxt(APP_DIR / "alpha_est.csv", np.array([alpha_mean]), fmt="%.17g")
    np.savetxt(APP_DIR / "sigma_est.csv", np.array([sigma_mean]), fmt="%.17g")
    np.savetxt(APP_DIR / "rho_est.csv", rho_mean, fmt="%.17g")
    np.savetxt(APP_DIR / "beta_est.csv", beta_mean, fmt="%.17g")

    print("Posterior means:")
    print(f"alpha: {alpha_mean}")
    print(f"sigma: {sigma_mean}")
    print("rho:  ", *rho_mean)
    print("beta: ", *beta_mean)


if __name__ == "__main__":
    main()

